import sys,json,os
P=sys.argv[1]
_D=os.path.dirname(os.path.abspath(__file__))
src=open(_D+'/hifi.py').read()
src=src[:src.index('# ---------- C4 Home ----------')]
exec(src)
LOGO=lambda size,col='#fff': f'<span style="{H}; display: flex; flex-direction: column; line-height: .88" aria-label="FreeWater"><span style="font-weight: 300; font-size: {size}px; color: {col}">free</span><span style="font-weight: 700; font-size: {size}px; color: {SKY}">water</span></span>'
def side(active):
    items=[("Overview","HfAdOverview.dc.html"),("Campaigns","HfAdCreative.dc.html"),("Creative library","#"),("Reports","#"),("Billing","#")]
    nav=''.join(f'<a href="{h}" style="display: block; padding: 10px 14px; border-radius: 10px; font-size: 15px; text-decoration: none; {"background: #1C1F22; color: #fff; font-weight: 700" if n==active else "color: #9AA4AD"}">{n}</a>' for n,h in items)
    return f'''<div style="width: 232px; flex: none; background: #000; color: #fff; padding: 28px 16px 24px; box-sizing: border-box; display: flex; flex-direction: column; gap: 4px">
<div style="padding: 0 14px 28px">{LOGO(30)}</div>{nav}
<div style="margin-top: auto; display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-radius: 12px; background: #1C1F22"><span style="width: 34px; height: 34px; border-radius: 8px; background: #3E4A47; color: #C7A86A; display: flex; align-items: center; justify-content: center; font-family: Georgia, serif; font-weight: 700; font-size: 18px">M</span><span style="display: flex; flex-direction: column"><span style="font-size: 14px; font-weight: 700">Marquette</span><span style="font-size: 12px; color: #9AA4AD">Fulton Market, Chicago</span></span></div></div>'''
def ask(t):
    return f'<div style="display: flex; align-items: center; gap: 12px; height: 50px; border-radius: 25px; background: {ICE}; padding: 0 8px 0 20px"><span style="font-size: 15px; color: {SUB}; flex: 1 1 auto">{t}</span><span style="width: 36px; height: 36px; border-radius: 18px; background: #000; color: #fff; display: flex; align-items: center; justify-content: center">{ICON["up"]}</span></div>'
def frame(name,title,body):
    inner=f'<div style="width: 1440px; height: 900px; box-sizing: border-box; background: {WHITE}; {B}; color: #000; display: flex">{body}</div>'
    write(name,title,1440,900,inner)

# ---------- A2 Overview ----------
kpi=''.join(f'<div style="display: flex; flex-direction: column; gap: 2px; padding-right: 20px; {"border-right: 1px solid "+LINE if i<4 else ""}"><span style="font-size: 13px; color: {SUB}">{a}</span><span style="{H}; font-weight: 700; font-size: 34px; letter-spacing: -0.01em">{b}</span><span style="font-size: 12px; color: {SUB}">{c}</span></div>' for i,(a,b,c) in enumerate([("Bottles with your ad","4,180","this week"),("Scans","512","12.2% of bottles"),("AR tours started","196","38% of scans"),("Tour requests","41","from scans and AR"),("Spent","$ TOTAL","prints, scans, AR")]))
fun=''.join(f'<div style="display: grid; grid-template-columns: 120px 1fr 56px; gap: 12px; align-items: center"><span style="font-size: 14px; color: {SUB}">{a}</span><span style="height: 14px; border-radius: 7px; background: {ICE}"><span style="display: block; width: {w}%; min-width: 14px; height: 14px; border-radius: 7px; background: {c}"></span></span><span style="font-size: 14px; font-weight: 700; text-align: right">{b}</span></div>' for a,b,w,c in [("Bottles","4,180",100,"#000"),("Scans","512",12.2,SKY),("AR tours","196",4.7,SKY),("Tour requests","41",1,DSKY)])
days=[48,55,52,60,78,92,70]
bars=''.join(f'<div style="flex: 1 1 0; display: flex; flex-direction: column; align-items: center; gap: 6px; height: 100%; justify-content: flex-end"><span style="font-size: 11px; color: {SUB}">{round(v*0.9)}</span><span style="width: 100%; height: {v}%; border-radius: 8px 8px 3px 3px; background: {"#000" if i==5 else SKY}"></span><span style="font-size: 12px; color: {SUB}">{d}</span></div>' for i,(d,v) in enumerate(zip(["Mon","Tue","Wed","Thu","Fri","Sat","Sun"],days)))
rows=[("CHI-007, Randolph St","Machine","1,240","212","61","9"),("Route 4, West Loop","12-packs","960","118","41","12"),("CHI-012, Fulton Market","Machine","880","96","35","8"),("Route 9, River North","24-packs","640","52","18","7"),("CHI-020, Union Park","Machine","460","34","14","5")]
th=''.join(f'<th style="text-align: {"left" if i<2 else "right"}; font-size: 13px; font-weight: 500; color: {SUB}; padding: 0 10px 10px">{h}</th>' for i,h in enumerate(["Place","Type","Bottles","Scans","AR tours","Requests"]))
tr=''.join('<tr>'+''.join(f'<td style="text-align: {"left" if i<2 else "right"}; font-size: 14px; padding: 11px 10px; border-top: 1px solid {LINE}; {"font-weight: 700" if i in (0,5) else ("color: "+SUB if i==1 else "")}">{c}</td>' for i,c in enumerate(r))+'</tr>' for r in rows)
spend=''.join(f'<div style="display: flex; justify-content: space-between; font-size: 14px; padding: 8px 0; border-top: 1px solid #22272B"><span style="color: #A7B4BF">{a}</span><span style="font-weight: 700">{b}</span></div>' for a,b in [("4,180 printed ads","$ —"),("512 scans","$ —"),("196 AR tours","$ —"),("Commission","$0, no purchases")])
body=side("Overview")+f'''<div style="flex: 1 1 auto; min-width: 0; padding: 30px 40px; display: flex; flex-direction: column; gap: 20px; box-sizing: border-box">
<div style="display: flex; justify-content: space-between; align-items: center"><div style="display: flex; flex-direction: column; gap: 4px"><span style="{H}; font-weight: 700; font-size: 32px">Overview</span><span style="display: flex; align-items: center; gap: 8px; font-size: 14px; color: {SUB}"><span style="width: 8px; height: 8px; border-radius: 4px; background: #2DBE6C"></span>Live. Your ad printed 4 seconds ago at CHI-007.</span></div>
<div style="display: flex; gap: 8px; align-items: center"><span style="padding: 9px 16px; border-radius: 20px; background: {ICE}; font-size: 14px; font-weight: 700">Last 7 days</span><a href="HfAdCreative.dc.html" style="padding: 12px 22px; border-radius: 24px; background: #000; color: #fff; font-size: 15px; font-weight: 700; text-decoration: none">New campaign</a></div></div>
{ask("Ask anything, like which machine sent the most tour requests this week")}
<div style="display: grid; grid-template-columns: repeat(5, 1fr); gap: 20px">{kpi}</div>
<div style="display: grid; grid-template-columns: 1fr 1fr 330px; gap: 20px; height: 260px">
<div style="border-radius: 20px; background: {ICE}; padding: 20px 22px; display: flex; flex-direction: column; gap: 16px"><span style="font-size: 15px; font-weight: 700">From bottle to tour request</span><div style="display: flex; flex-direction: column; gap: 16px; justify-content: center; flex: 1 1 auto">{fun}</div></div>
<div style="border-radius: 20px; background: {ICE}; padding: 20px 22px; display: flex; flex-direction: column; gap: 12px"><div style="display: flex; justify-content: space-between"><span style="font-size: 15px; font-weight: 700">Scans by day</span><span style="font-size: 13px; color: {SUB}">Saturday was your best day</span></div><div style="display: flex; gap: 12px; flex: 1 1 auto; min-height: 0">{bars}</div></div>
<div style="border-radius: 20px; background: #000; color: #fff; padding: 20px 22px; display: flex; flex-direction: column; gap: 4px"><span style="font-size: 15px; font-weight: 700; padding-bottom: 6px">What you paid</span>{spend}<div style="display: flex; justify-content: space-between; font-size: 16px; font-weight: 700; padding-top: 10px; border-top: 1px solid #22272B"><span>Total</span><span>$ TOTAL</span></div><a href="LedgerLive.dc.html" style="margin-top: auto; font-size: 13px; color: {SKY}; text-decoration: none; font-weight: 700">Every charge is on the public ledger</a></div></div>
<div style="display: grid; grid-template-columns: 1fr 420px; gap: 20px; flex: 1 1 auto; min-height: 0">
<div style="display: flex; flex-direction: column; gap: 10px"><span style="font-size: 15px; font-weight: 700">Top places</span><table style="border-collapse: collapse; width: 100%"><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>
<div style="display: flex; flex-direction: column; gap: 10px"><div style="display: flex; justify-content: space-between"><span style="font-size: 15px; font-weight: 700">Your ad, as printed</span><a href="#" style="font-size: 13px; font-weight: 700; color: {DSKY}; text-decoration: none">Fall leasing</a></div><img src="img/marquette-label.jpg" alt="The Marquette label as printed, with the FreeWater panel on the right" style="width: 100%; border-radius: 14px; display: block"><span style="font-size: 13px; color: {SUB}">Full wrap. Your QR opens the Marquette AR tour; the black panel is FreeWater&#39;s.</span></div></div></div>'''
frame('HfAdOverview','A2 Overview · hi-fi',body)

# ---------- A4.1 Creative ----------
steps=["Creative","Where and who","Scan experience","Budget","Review"]
st=''.join(f'<span style="display: flex; align-items: center; gap: 8px; font-size: 14px; {"font-weight: 700" if i==0 else "color: "+SUB}"><span style="width: 26px; height: 26px; border-radius: 13px; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; {"background: #000; color: #fff" if i==0 else "background: "+ICE}">{i+1}</span>{s}</span>'+('<span style="flex: 1 1 auto; height: 2px; background: '+LINE+'; min-width: 20px"></span>' if i<4 else '') for i,s in enumerate(steps))
def bubble_you(t,files=''):
    return f'<div style="align-self: flex-end; max-width: 330px; display: flex; flex-direction: column; gap: 6px; align-items: flex-end">{files}<div style="background: #000; color: #fff; border-radius: 18px 18px 4px 18px; padding: 11px 14px; font-size: 14px; line-height: 1.45">{t}</div></div>'
def bubble_ai(t,chips):
    c=''.join(f'<a href="#" style="padding: 7px 13px; border-radius: 16px; {"background: "+ICE if i==0 else "border: 1.5px solid "+LINE}; font-size: 13px; font-weight: 700; text-decoration: none; color: #000">{x}</a>' for i,x in enumerate(chips))
    return f'<div style="max-width: 350px; display: flex; flex-direction: column; gap: 8px"><div style="font-size: 14px; line-height: 1.5">{t}</div><div style="display: flex; gap: 6px; flex-wrap: wrap">{c}</div></div>'
files='<div style="display: flex; gap: 6px">'+''.join(f'<span style="padding: 8px 12px; border-radius: 10px; background: {ICE}; font-size: 12px; font-weight: 700">{f}</span>' for f in ["Brand guide.pdf","12 building photos","Logo.svg"])+'</div>'
chat=bubble_you("Fall leasing ad for our four buildings. Lead with the photos, keep our charcoal and gold, and point the QR to the AR tour.",files)+bubble_ai("Here it is in every size. I used the charcoal and gold from your guide, one photo per building, and kept each QR clear of the seam.",["Show it on a bottle","Try a lighter version"])+bubble_you("In the small sizes, show just one building each.")+bubble_ai("Done. The Thompson leads the 1/6 version, EVO&#39;s pool the 1/3, and Parq Fulton with Mason the half label. The full wrap keeps all four.",["Show all sizes"])
sizes=f'''<div style="display: grid; grid-template-columns: 0.55fr 0.55fr 1fr; gap: 14px; align-items: end">
<div style="display: flex; flex-direction: column; gap: 6px"><img src="img/mq-thompson.jpg" alt="One-sixth slot version" style="width: 100%; height: 230px; object-fit: cover; object-position: center bottom; border-radius: 12px; display: block"><span style="font-size: 13px; font-weight: 700">1/6 of the label</span></div>
<div style="display: flex; flex-direction: column; gap: 6px"><img src="img/mq-evo.jpg" alt="One-third slot version" style="width: 100%; height: 230px; object-fit: cover; object-position: center bottom; border-radius: 12px; display: block"><span style="font-size: 13px; font-weight: 700">1/3 of the label</span></div>
<div style="display: flex; flex-direction: column; gap: 6px"><img src="img/mq-parq-mason.jpg" alt="Half label version" style="width: 100%; height: 230px; object-fit: cover; object-position: center bottom; border-radius: 12px; display: block"><span style="font-size: 13px; font-weight: 700">1/2 of the label</span></div></div>'''
checks=''.join(f'<div style="display: flex; justify-content: space-between; font-size: 14px; padding: 8px 0; border-top: 1px solid {LINE}"><span>{a}</span><span style="color: #1F8A4C; font-weight: 700">{b}</span></div>' for a,b in [("Sharp enough to print","Yes"),("Text readable at 1/6","Yes"),("QR clear of the seam","Yes"),("Content rules","Likely to pass")])
body=side("Campaigns")+f'''<div style="flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column">
<div style="padding: 26px 40px 18px; display: flex; flex-direction: column; gap: 16px; border-bottom: 1px solid {LINE}"><div style="display: flex; justify-content: space-between; align-items: center"><span style="{H}; font-weight: 700; font-size: 28px">New campaign</span><a href="#" style="font-size: 14px; font-weight: 700; color: {DSKY}; text-decoration: none">Save draft</a></div><div style="display: flex; align-items: center; gap: 12px">{st}</div></div>
<div style="flex: 1 1 auto; display: flex; min-height: 0">
<div style="width: 430px; flex: none; border-right: 1px solid {LINE}; padding: 22px 26px; box-sizing: border-box; display: flex; flex-direction: column; gap: 16px">
<div style="display: flex; flex-direction: column; gap: 14px; flex: 1 1 auto; overflow: hidden">{chat}</div>
<div style="border: 1.5px solid {LINE}; border-radius: 24px; padding: 6px 6px 6px 8px; display: flex; align-items: center; gap: 6px"><a href="#" aria-label="Attach" style="width: 36px; height: 36px; border-radius: 18px; background: {ICE}; display: flex; align-items: center; justify-content: center; color: #000">{ICON["plus"]}</a><span style="flex: 1 1 auto; font-size: 14px; color: #8A99AB">Describe your ad or a change</span><a href="#" aria-label="Talk" style="width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; color: {SUB}">{ICON["mic"]}</a><a href="#" aria-label="Send" style="width: 36px; height: 36px; border-radius: 18px; background: #000; color: #fff; display: flex; align-items: center; justify-content: center">{ICON["up"]}</a></div></div>
<div style="flex: 1 1 auto; min-width: 0; padding: 22px 34px; display: flex; flex-direction: column; gap: 16px">
<div style="display: flex; justify-content: space-between; align-items: baseline"><span style="font-size: 15px; font-weight: 700">Made in every size from your artwork</span><a href="#" style="font-size: 13px; font-weight: 700; color: {DSKY}; text-decoration: none">Upload finished artwork instead</a></div>
{sizes}
<div style="display: grid; grid-template-columns: 1fr 300px; gap: 20px; flex: 1 1 auto; min-height: 0">
<div style="display: flex; flex-direction: column; gap: 8px"><span style="font-size: 15px; font-weight: 700">Full wrap</span><img src="img/marquette-label.jpg" alt="Full wrap version next to the FreeWater panel" style="width: 100%; border-radius: 12px; display: block"></div>
<div style="display: flex; flex-direction: column; gap: 4px"><span style="font-size: 15px; font-weight: 700; padding-bottom: 6px">Checks</span>{checks}</div></div></div></div>
<div style="padding: 14px 40px; border-top: 1px solid {LINE}; display: flex; justify-content: space-between; align-items: center"><span style="font-size: 13px; color: {SUB}">You pay for confirmed prints, real scans and AR tours. Never for failures.</span><a href="AdWhere.dc.html" style="padding: 13px 26px; border-radius: 24px; background: #000; color: #fff; font-size: 15px; font-weight: 700; text-decoration: none">Next: where and who</a></div></div>'''
