c=json.load(open(P+'canvas.json'))
y=15700
for i,(n,t) in enumerate([('HfAdOverview','A2 · Advertiser overview'),('HfAdCreative','A4.1 · Creative, designed by chat')]):
    c['boards'][n+'.dc.html']={"x":i*1520,"y":y,"w":1440,"h":900,"title":t,"is_interactive":True}
    if n+'.dc.html' not in c['order']: c['order'].append(n+'.dc.html')
